mapper.select:
SELECT  FROM dreams

    workspace_uuid = #{params.WorkspaceUUID}
    AND archived_at IS NULL
    AND (created_at < #{params.CursorCreatedAt} OR (created_at = #{params.CursorCreatedAt} AND uuid < #{params.CursorUUID}))

ORDER BY created_at DESC, uuid DESC LIMIT #{params.Limit}

SELECT  FROM dreams
WHERE status = #{status} AND archived_at IS NULL
ORDER BY created_at ASC, uuid ASC LIMIT #{limit}

mapper.update:
UPDATE dreams
SET claim_expires_at = #{params.ClaimExpiresAt},
    updated_at = #{params.Now}
WHERE workspace_uuid = #{params.WorkspaceUUID}
  AND external_id = #{params.ExternalID}
  AND status = 'pending'
  AND claimed_by_worker_id = #{params.WorkerID}
  AND archived_at IS NULL

UPDATE dreams
SET status = 'running',
    execution_state = 'running',
    started_at = COALESCE(started_at, #{params.Now}),
    next_attempt_at = NULL,
    claimed_by_worker_id = NULL,
    claim_expires_at = NULL,
    last_error = NULL,
    updated_at = #{params.Now}
WHERE workspace_uuid = #{params.WorkspaceUUID}
  AND external_id = #{params.ExternalID}
  AND archived_at IS NULL
  AND status = 'pending'
  AND claimed_by_worker_id = #{params.WorkerID}
  AND outputs->0->>'memory_store_id' = #{params.OutputMemoryStoreID}
  AND outputs->0->>'internal_session_id' = #{params.InternalSessionID}
RETURNING

UPDATE dreams
SET usage = CAST(#{params.Usage,sensitive=true} AS jsonb),
    updated_at = #{params.Now}
WHERE workspace_uuid = #{params.WorkspaceUUID}
  AND external_id = #{params.ExternalID}
  AND archived_at IS NULL
  AND status = 'running'
RETURNING

UPDATE dreams SET archived_at = COALESCE(archived_at, NOW()), updated_at = NOW()
WHERE workspace_uuid = #{workspaceUUID} AND external_id = #{externalID}
RETURNING
